"use client";

import { Line } from "@react-three/drei";
import { CEO_NODE, SPOKE_NODES } from "./layout";
import type { AgentId, AgentStatusValue } from "@/lib/types";

interface ConnectionLinesProps {
  agents: Record<AgentId, { status: AgentStatusValue }>;
}

export default function ConnectionLines({ agents }: ConnectionLinesProps) {
  return (
    <>
      {SPOKE_NODES.map((node) => {
        const status = agents[node.id]?.status ?? "idle";
        const active = status === "active" || status === "done";
        return (
          <Line
            key={node.id}
            points={[CEO_NODE.position, node.position]}
            color={active ? node.color : "#2a2f3d"}
            lineWidth={active ? 2 : 1}
            transparent
            opacity={active ? 0.85 : 0.25}
          />
        );
      })}
    </>
  );
}
