"use client";

import { useMemo, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";
import { CEO_NODE, SPOKE_NODES } from "./layout";
import type { AgentId, AgentStatusValue } from "@/lib/types";

const PER_LINE = 5;
const TOTAL = SPOKE_NODES.length * PER_LINE;

interface ConnectionParticlesProps {
  agents: Record<AgentId, { status: AgentStatusValue }>;
}

/**
 * A single InstancedMesh (one draw call) carries all particles across all 4 spokes.
 * Inactive spokes just get their instances scaled to 0 rather than removed, which keeps
 * this cheap enough for a laptop GPU during a live demo.
 */
export default function ConnectionParticles({ agents }: ConnectionParticlesProps) {
  const meshRef = useRef<THREE.InstancedMesh>(null);
  const dummy = useMemo(() => new THREE.Object3D(), []);
  const ceoPos = useMemo(() => new THREE.Vector3(...CEO_NODE.position), []);

  useFrame((state) => {
    if (!meshRef.current) return;
    const t = state.clock.elapsedTime;
    let i = 0;
    for (const node of SPOKE_NODES) {
      const status = agents[node.id]?.status ?? "idle";
      const active = status === "active" || status === "done";
      const target = new THREE.Vector3(...node.position);
      for (let p = 0; p < PER_LINE; p++) {
        const phase = (t * 0.55 + p / PER_LINE) % 1;
        dummy.position.copy(ceoPos).lerp(target, phase);
        dummy.scale.setScalar(active ? 0.055 : 0);
        dummy.updateMatrix();
        meshRef.current.setMatrixAt(i, dummy.matrix);
        i++;
      }
    }
    meshRef.current.instanceMatrix.needsUpdate = true;
  });

  return (
    <instancedMesh ref={meshRef} args={[undefined, undefined, TOTAL]}>
      <sphereGeometry args={[1, 6, 6]} />
      <meshBasicMaterial color="#8be9ff" toneMapped={false} />
    </instancedMesh>
  );
}
