"use client";

import { Canvas } from "@react-three/fiber";
import { OrbitControls } from "@react-three/drei";
import { EffectComposer, Bloom } from "@react-three/postprocessing";
import AgentNode from "./AgentNode";
import ConnectionLines from "./ConnectionLines";
import ConnectionParticles from "./ConnectionParticles";
import { AGENT_LAYOUT } from "./layout";
import { useSwarmStore } from "@/lib/store";

interface AgentSwarmSceneProps {
  /** Slower/smaller footprint for the hero-screen background vs. the working-screen hero shot. */
  compact?: boolean;
}

export default function AgentSwarmScene({ compact = false }: AgentSwarmSceneProps) {
  const agents = useSwarmStore((s) => s.agents);

  return (
    <Canvas
      dpr={[1, 1.5]}
      camera={{ position: [0, 1.3, compact ? 8.5 : 6.8], fov: 42 }}
      gl={{ antialias: true, powerPreference: "high-performance", alpha: false }}
    >
      <color attach="background" args={["#05060a"]} />
      <ambientLight intensity={0.35} />
      <pointLight position={[5, 5, 5]} intensity={35} color="#4f7dff" />
      <pointLight position={[-5, -3, -4]} intensity={20} color="#9b6bff" />

      <group rotation={[0.05, 0, 0]}>
        {AGENT_LAYOUT.map((cfg) => (
          <AgentNode key={cfg.id} config={cfg} status={agents[cfg.id]?.status ?? "idle"} />
        ))}
        <ConnectionLines agents={agents} />
        <ConnectionParticles agents={agents} />
      </group>

      <OrbitControls
        enablePan={false}
        enableZoom={false}
        autoRotate
        autoRotateSpeed={compact ? 0.5 : 0.35}
        minPolarAngle={Math.PI / 2.6}
        maxPolarAngle={Math.PI / 1.7}
      />

      <EffectComposer multisampling={0}>
        <Bloom intensity={0.85} luminanceThreshold={0.15} luminanceSmoothing={0.4} mipmapBlur />
      </EffectComposer>
    </Canvas>
  );
}
