"use client";

import { useRef } from "react";
import { useFrame } from "@react-three/fiber";
import { Text } from "@react-three/drei";
import * as THREE from "three";
import type { AgentNodeConfig } from "./layout";
import type { AgentStatusValue } from "@/lib/types";

interface AgentNodeProps {
  config: AgentNodeConfig;
  status: AgentStatusValue;
}

export default function AgentNode({ config, status }: AgentNodeProps) {
  const meshRef = useRef<THREE.Mesh>(null);
  const glowRef = useRef<THREE.Mesh>(null);

  useFrame((state) => {
    const t = state.clock.elapsedTime;
    const pulse = status === "active" ? 1 + Math.sin(t * 4.2) * 0.14 : status === "done" ? 1.05 : 0.92;

    if (meshRef.current) {
      const target = config.radius * pulse;
      meshRef.current.scale.setScalar(THREE.MathUtils.lerp(meshRef.current.scale.x || target, target, 0.15));
      meshRef.current.rotation.y = t * 0.25;
      meshRef.current.rotation.x = Math.sin(t * 0.2) * 0.15;
    }
    if (glowRef.current) {
      const glowTarget = config.radius * (pulse + (status === "active" ? 0.35 : 0.15));
      glowRef.current.scale.setScalar(THREE.MathUtils.lerp(glowRef.current.scale.x || glowTarget, glowTarget, 0.12));
    }
  });

  const color = status === "error" ? "#f87171" : config.color;
  const emissiveIntensity = status === "idle" ? 0.3 : status === "active" ? 2.4 : status === "done" ? 1.2 : 1.8;

  return (
    <group position={config.position}>
      <mesh ref={meshRef}>
        <icosahedronGeometry args={[1, 1]} />
        <meshStandardMaterial color={color} emissive={color} emissiveIntensity={emissiveIntensity} roughness={0.25} metalness={0.5} />
      </mesh>
      <mesh ref={glowRef}>
        <icosahedronGeometry args={[1, 0]} />
        <meshBasicMaterial color={color} transparent opacity={status === "idle" ? 0.05 : 0.12} depthWrite={false} />
      </mesh>
      <Text
        position={[0, -config.radius - 0.32, 0]}
        fontSize={0.24}
        color="#e5e7eb"
        anchorX="center"
        anchorY="top"
        outlineWidth={0.012}
        outlineColor="#05060a"
      >
        {config.label}
      </Text>
    </group>
  );
}
